// Brand marks used across the site. To use a photo of a real struck plate instead of
// the generated SVG, drop the image in public/brand/ and change `src` (and the
// width/height to the photo's pixel size) here. Nothing else needs to change.
// The SVGs are generated by scripts/build-brand.mjs (npm run brand).

import type { ImageMetadata } from 'astro';

export type Mark = { src: string; width: number; height: number; alt: string };

// Official logo images (src/assets/brand/mce-plate.png, mce-seal.png). When present they
// replace the generated SVG marks everywhere; see src/assets/brand/README.md.
const official = import.meta.glob<{ default: ImageMetadata }>('../assets/brand/mce-*.png', { eager: true });
export const platePng: ImageMetadata | undefined = official['../assets/brand/mce-plate.png']?.default;
export const sealPng: ImageMetadata | undefined = official['../assets/brand/mce-seal.png']?.default;
export const brandAlt = 'Mel-Co-Ed, Inc. — Pawtucket, Rhode Island, Est. 1948';

export const brand = {
  /** Primary plate: footer, OG image, large placements. */
  plate: { src: '/brand/plate.svg', width: 640, height: 300, alt: 'Mel-Co-Ed, Inc.' },
  /** Compact plate for the header. */
  plateCompact: { src: '/brand/plate-compact.svg', width: 300, height: 124, alt: 'Mel-Co-Ed, Inc.' },
  /** Round brass seal: footer, About, badges. */
  seal: { src: '/brand/seal.svg', width: 400, height: 400, alt: 'Mel-Co-Ed, Inc. seal: Est. 1948, Pawtucket, R.I.' },
  /** Made-in badge (verified claim). */
  madeIn: { src: '/brand/seal-made-in.svg', width: 400, height: 400, alt: 'Made in Rhode Island, USA. Pawtucket Proud.' },
} satisfies Record<string, Mark>;

/** Verified origin claim. Primary line + small secondary line. */
export const madeIn = { primary: 'Made in Rhode Island, USA', secondary: 'Pawtucket Proud' };
